def carnet(n):
    return {p: sample(range(4, 20), randint(1, 4)) for p in sample(PRENOMS, n)}
cases = []
if kind == "moyennes":
    fname, params = choice(["moyennes", "calcul_moyennes"]), "notes"
    consigne = "renvoie un **nouveau dictionnaire** qui associe à chaque élève la moyenne de ses notes"
    for n in [3, 0, 1, 4, 2]:
        d = carnet(n)
        cases.append(((d,), {p: sum(v) / len(v) for p, v in d.items()}))
    ref = f"def {fname}(notes):\n    res = {{}}\n    for eleve, liste in notes.items():\n        res[eleve] = sum(liste) / len(liste)\n    return res\n"
elif kind == "meilleur":
    fname, params = choice(["meilleur_eleve", "premier"]), "notes"
    consigne = "renvoie le nom de l'élève qui a la **meilleure moyenne** (le dictionnaire n'est pas vide et les moyennes sont toutes différentes)"
    for n in [3, 1, 4, 2, 5]:
        while True:
            d = carnet(n)
            moy = [sum(v) / len(v) for v in d.values()]
            if len(set(moy)) == len(moy):
                break
