           f"        if meilleur is None or m > meilleure_moy:\n            meilleur, meilleure_moy = eleve, m\n    return meilleur\n")
else:
    fname, params = choice(["nb_notes", "total_notes"]), "notes"
    consigne = "renvoie le **nombre total de notes** enregistrées, tous élèves confondus"
    for n in [3, 0, 1, 4, 5]:
        d = carnet(n)
        cases.append(((d,), sum(len(v) for v in d.values())))
    ref = f"def {fname}(notes):\n    n = 0\n    for liste in notes.values():\n        n = n + len(liste)\n    return n\n"
